95	        }
96	        // Try to find it in the global list
97	        ContentProviderRecord record = mSingletonByClass.get(name);
98	        if (record != null) {
99	            return record;
100	        }
101	
102	        // Check the current user's list
103	        return getProvidersByClass(userId).get(name);
