1521	        for (int i = proc.mProviders.numberOfProviders() - 1; i >= 0; i--) {
1522	            if (!proc.mProviders.getProviderAt(i).connections.isEmpty()) {
1523	                return true;
1524	            }
1525	        }
1526	        return false;
1527	    }
